const problems = problemRows.map((r,i)=>({id:String(i+1).padStart(3,"0"),title:r[0],category:r[1],problem:r[2],approach:r[3],hardware:r[4],question:r[5],angle:r[6],refs:r[7]}));
const grid=document.querySelector("#idea-grid"),search=document.querySelector("#search"),filter=document.querySelector("#category-filter"),count=document.querySelector("#result-count"),empty=document.querySelector("#empty-state"),dialog=document.querySelector("#idea-dialog"),dialogContent=document.querySelector("#dialog-content");
const tabs=[...document.querySelectorAll(".catalog-tab")];
let activeTab="ideas";
document.querySelector("#ideas-tab-count").textContent=ideas.length;
document.querySelector("#problems-tab-count").textContent=problems.length;
[...new Set([...ideas,...problems].map(x=>x.category))].sort().forEach(c=>{const o=document.createElement("option");o.value=c;o.textContent=c;filter.append(o)});
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function activeEntries(){return activeTab==="ideas"?ideas:problems;}
function render(){const entries=activeEntries(),q=search.value.trim().toLowerCase(),cat=filter.value;const found=entries.filter(x=>(cat==="all"||x.category===cat)&&(!q||[x.title,x.category,x.problem,x.approach,x.hardware,x.question,x.angle].join(" ").toLowerCase().includes(q)));document.querySelector("#active-count").textContent=entries.length;document.querySelector("#active-count-label").textContent=activeTab==="ideas"?"thesis ideas":"problem statements";count.textContent=`${String(found.length).padStart(2,"0")} / ${entries.length} ${activeTab.toUpperCase()}`;empty.hidden=found.length!==0;grid.hidden=found.length===0;grid.innerHTML=found.map(x=>`<article class="idea-card" tabindex="0" role="button" data-id="${x.id}" aria-label="Open ${escapeHTML(x.title)}"><div class="card-top"><span class="card-number">${activeTab==="ideas"?"FN":"PB"}—${x.id}</span><span class="card-type">${escapeHTML(x.category)}</span></div><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.problem)}</p><div class="card-foot"><span class="hardware">${escapeHTML(x.hardware)}</span><span class="card-arrow" aria-hidden="true">↗</span></div></article>`).join("");}
function switchTab(name){activeTab=name;tabs.forEach(t=>{const selected=t.dataset.tab===name;t.classList.toggle("active",selected);t.setAttribute("aria-selected",String(selected));t.tabIndex=selected?0:-1});search.placeholder=name==="ideas"?"Search ideas, hardware, or problems…":"Search problems, technology, or field…";filter.value="all";render();}
function openEntry(id){const x=activeEntries().find(y=>y.id===id);if(!x)return;const isIdea=activeTab==="ideas",refs=x.refs.map(k=>papers[k]).filter(Boolean);dialogContent.innerHTML=`<div class="dialog-body"><div class="dialog-kicker">${isIdea?"FIELD NOTE FN":"OPEN PROBLEM PB"}—${x.id} / ${escapeHTML(x.category.toUpperCase())}</div><h2 id="dialog-title">${escapeHTML(x.title)}</h2><p class="dialog-deck">${escapeHTML(x.problem)}</p><div class="detail-grid"><section class="detail-block"><h3>Technology opportunity</h3><p>${escapeHTML(x.approach)}</p></section><section class="detail-block"><h3>Research question</h3><p>${escapeHTML(x.question)}</p></section><section class="detail-block"><h3>${isIdea?"Prototype stack":"Possible prototype"}</h3><p>${escapeHTML(x.hardware)}</p></section><section class="detail-block"><h3>${isIdea?"Improvement angle":"Research opening"}</h3><p>${escapeHTML(x.angle)}. Treat this as a gap hypothesis and verify it against recent work.</p></section></div><section class="papers"><h3>IEEE papers to start your RRL</h3><ol class="paper-list">${refs.map(p=>`<li><strong>${escapeHTML(p.title)}</strong><span class="paper-meta">${escapeHTML(p.authors)} · ${escapeHTML(p.venue)}<br>IEEE source · DOI: ${escapeHTML(p.doi)}</span><a class="paper-link" href="https://doi.org/${encodeURIComponent(p.doi)}" target="_blank" rel="noopener noreferrer">Open paper ↗</a><span class="paper-meta">Relevance: ${escapeHTML(p.fit)}</span></li>`).join("")}</ol><p class="paper-note">These papers support the problem area or method; they do not prove that a proposed solution is novel. Search IEEE Xplore for recent, system-specific work and confirm the research gap with an adviser.</p></section></div>`;dialog.showModal();}
tabs.forEach(t=>t.addEventListener("click",()=>switchTab(t.dataset.tab)));document.querySelector(".catalog-tabs").addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(e.key))return;e.preventDefault();let i=tabs.indexOf(document.activeElement);if(e.key==="Home")i=0;else if(e.key==="End")i=tabs.length-1;else i=(i+(e.key==="ArrowRight"?1:-1)+tabs.length)%tabs.length;tabs[i].focus();switchTab(tabs[i].dataset.tab)});grid.addEventListener("click",e=>{const card=e.target.closest(".idea-card");if(card)openEntry(card.dataset.id)});grid.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches(".idea-card")){e.preventDefault();openEntry(e.target.dataset.id)}});search.addEventListener("input",render);filter.addEventListener("change",render);document.querySelector("#clear-filters").addEventListener("click",()=>{search.value="";filter.value="all";render()});document.querySelector(".dialog-close").addEventListener("click",()=>dialog.close());dialog.addEventListener("click",e=>{if(e.target===dialog)dialog.close()});document.addEventListener("keydown",e=>{if(e.key==="/"&&!dialog.open&&!/input|textarea/i.test(document.activeElement.tagName)){e.preventDefault();search.focus()}});switchTab("ideas");
